const visual = {
  prepare: function (input) {
    var texts = [
      '解一元一次方程',
      '7x+-3=1x+4',
      '第1步 移项',
      '7x-1x=4+3',
      '把 1x 移到左边、-3 移到右边',
      '第2步 合并同类项',
      '6x=7',
      '左边 7x-1x=6x，右边 4+3=7',
      '第3步 系数化为 1',
      'x=7/6',
      '两边同时除以 6'
    ];
    var out = [];
    for (var i = 0; i < texts.length; i++) {
      out.push({ kind: 'text', payload: texts[i] });
    }
    return out;
  },
  render: function (input, metrics) {
    var W = (input.viewport && input.viewport.widthDu) || 420;
    var H = (input.viewport && input.viewport.heightDu) || 640;
    var margin = 20;
    var cardX = margin;
    var cardW = W - margin * 2;
    var titleY = margin + 20;
    var eqY = titleY + 34;
    var top = eqY + 40;
    var gap = 26;
    var bottomPad = 20;
    var boxH = (H - top - bottomPad - gap * 2) / 3;
    if (boxH < 100) { boxH = 100; }
    var pathDefs = [];
    var kids = [];
    var pid = 0;
    function addShape(commands, stroke, fill) {
      pid = pid + 1;
      var id = 'p' + pid;
      pathDefs.push({ id: id, commands: commands });
      var node = { type: 'path', pathId: id, stroke: stroke };
      if (fill) { node.fill = fill; }
      kids.push(node);
    }
    function addText(text, x, y, size, fill, anchor) {
      var node = { type: 'label', text: text, x: x, y: y, fontSize: size, fill: fill };
      if (anchor) { node.textAnchor = anchor; }
      kids.push(node);
    }
    function rect(x, y, w, h) {
      return visualSdk.polyline([[x, y], [x + w, y], [x + w, y + h], [x, y + h], [x, y]]);
    }
    addText('解一元一次方程', W / 2, titleY, 18, '#1b2a3d', 'middle');
    addText('7x+-3=1x+4', W / 2, eqY, 22, '#0b60c9', 'middle');
    var steps = [
      { n: '1', t: '移项', eq: '7x-1x=4+3', note: '把 1x 移到左边、-3 移到右边' },
      { n: '2', t: '合并同类项', eq: '6x=7', note: '左边 7x-1x=6x，右边 4+3=7' },
      { n: '3', t: '系数化为 1', eq: 'x=7/6', note: '两边同时除以 6' }
    ];
    for (var i = 0; i < steps.length; i++) {
      var by = top + i * (boxH + gap);
      addShape(rect(cardX, by, cardW, boxH), '#8ea4c0', '#f5f9ff');
      addShape(visualSdk.circle(cardX + 34, by + 32, 15), '#0b60c9', '#0b60c9');
      addText(steps[i].n, cardX + 34, by + 38, 15, '#ffffff', 'middle');
      addText('第' + steps[i].n + '步 ' + steps[i].t, cardX + 58, by + 38, 17, '#1b2a3d');
      addText(steps[i].note, cardX + 58, by + 62, 13, '#5b6b80');
      addText(steps[i].eq, cardX + cardW / 2, by + boxH - 26, 22, '#0b60c9', 'middle');
      if (i < steps.length - 1) {
        addShape(visualSdk.arrow(W / 2, by + boxH + 4, W / 2, by + boxH + gap - 4, {}), '#8ea4c0');
      }
    }
    return {
      schemaVersion: 1,
      sceneId: 'solve-linear-flow',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: pathDefs,
      root: { type: 'group', children: kids }
    };
  }
};
